import { createClient, type Client } from "@libsql/client";

/**
 * Fails when a live database is missing any column the Prisma datamodel declares.
 *
 * Why this exists
 * ---------------
 * `db:push-turso` runs `scripts/push-to-turso.ts`, which executes
 * `prisma/schema.sql`. That file is generated by `prisma migrate diff --from-empty`,
 * so it contains only `CREATE TABLE IF NOT EXISTS` — never `ALTER TABLE`. On a
 * database that already has the table, every statement is a silent no-op, so the
 * push reports success while adding nothing.
 *
 * The consequence is that `prisma/migrations/` never runs in production, and any
 * column added to `schema.prisma` after the initial push silently does not exist
 * there. The app then fails at runtime with:
 *
 *   SQL_INPUT_ERROR: SQLite input error: no such column: main.Service.isCatchAll
 *
 * Local dev never catches it: `prisma migrate dev` applies the real migrations to
 * `dev.db`, so the column is always present locally.
 *
 * This compares the datamodel (via the generated schema.sql) against the live
 * database's actual columns and exits non-zero on any gap. Read-only.
 *
 * Usage:
 *   npm run db:check-drift                 # checks DATABASE_URL / TURSO_DATABASE_URL
 *   npm run db:check-drift -- --url=file:./dev.db
 *   npm run db:check-drift -- --json       # machine-readable, for a deploy gate
 *   npm run db:check-drift -- --required   # fail if no URL is configured
 *
 * To fix a reported gap, run the matching idempotent migration script, e.g.
 * `npm run db:migrate-prod`, rather than pushing schema.sql.
 */

interface ColumnSpec {
  table: string;
  column: string;
  // SQLite type text as it appears in schema.sql, used to report what is expected.
  type: string;
  notNull: boolean;
  defaultValue: string | null;
}

function parseSchemaSql(): ColumnSpec[] {
  const { readFileSync } = require("fs") as typeof import("fs");
  const path = require("path") as typeof import("path");

  const schema = readFileSync(path.join(process.cwd(), "prisma", "schema.sql"), "utf-8");

  const specs: ColumnSpec[] = [];
  const createTable = /CREATE TABLE IF NOT EXISTS "([^"]+)" \(([\s\S]*?)\n\);/g;

  for (const match of schema.matchAll(createTable)) {
    const table = match[1];
    const body = match[2];

    for (const rawLine of body.split("\n")) {
      const line = rawLine.trim().replace(/,$/, "");
      if (!line || line.startsWith("CONSTRAINT") || line.startsWith("PRIMARY KEY")) continue;

      const col = /^"([^"]+)"\s+([A-Z]+(?:\s+[A-Z]+)*?)\s*(NOT NULL)?\s*(DEFAULT\s+(.+?))?$/.exec(line);
      if (!col) continue;

      specs.push({
        table,
        column: col[1],
        type: col[2],
        notNull: Boolean(col[3]),
        defaultValue: col[4] ?? null,
      });
    }
  }

  return specs;
}

async function tableColumns(client: Client, table: string): Promise<Set<string>> {
  const res = await client.execute(`PRAGMA table_info("${table}")`);
  return new Set(res.rows.map((r) => String(r.name)));
}

async function main() {
  const args = process.argv.slice(2);
  const json = args.includes("--json");
  const required = args.includes("--required");
  const urlArg = args.find((a) => a.startsWith("--url="));

  // Accept either name. src/lib/db.ts reads DATABASE_URL, so that is what a deploy
  // platform has set; TURSO_DATABASE_URL is what the migration scripts use. Only
  // DATABASE_URL is guaranteed to exist in the environment that runs the app, so
  // both are honoured here rather than silently checking the wrong database.
  const url =
    (urlArg ? urlArg.slice("--url=".length) : undefined) ??
    process.env.TURSO_DATABASE_URL ??
    process.env.DATABASE_URL;
  const authToken = process.env.TURSO_AUTH_TOKEN ?? process.env.DATABASE_AUTH_TOKEN;

  if (!url) {
    if (required) {
      console.error(
        "Schema drift check: no database URL found.\n" +
          "Set DATABASE_URL (or TURSO_DATABASE_URL) to the production libsql:// URL.",
      );
      process.exit(2);
    }
    console.error("Set DATABASE_URL or TURSO_DATABASE_URL, or pass --url=<libsql://...>");
    process.exit(2);
  }

  const specs = parseSchemaSql();
  if (specs.length === 0) {
    console.error("Could not parse any columns out of prisma/schema.sql.");
    process.exit(2);
  }

  const client = createClient({ url, authToken });
  const label = url.startsWith("libsql") ? "production" : `local (${url})`;

  const missing: ColumnSpec[] = [];
  const absentTables: string[] = [];
  const tables = [...new Set(specs.map((s) => s.table))];

  for (const table of tables) {
    const cols = await tableColumns(client, table);
    if (cols.size === 0) {
      absentTables.push(table);
      continue;
    }
    for (const spec of specs.filter((s) => s.table === table)) {
      if (!cols.has(spec.column)) missing.push(spec);
    }
  }

  await client.close();

  if (json) {
    console.log(JSON.stringify({ url, label, absentTables, missing }, null, 2));
    process.exit(missing.length || absentTables.length ? 1 : 0);
  }

  console.log(`Schema drift check against ${label}`);
  console.log(`  tables checked: ${tables.length}`);
  console.log(`  columns checked: ${specs.length}`);

  if (absentTables.length) {
    console.log(`\nMISSING TABLES (${absentTables.length}):`);
    for (const t of absentTables) console.log(`  - ${t}`);
    console.log("\n  These tables do not exist at all. A first-time push is needed:");
    console.log("    npm run db:push-turso");
  }

  if (missing.length) {
    console.log(`\nMISSING COLUMNS (${missing.length}):`);
    for (const m of missing) {
      const def = m.defaultValue ? ` ${m.defaultValue.replace("DEFAULT ", "default ")}` : "";
      console.log(`  - ${m.table}.${m.column}  ${m.type}${m.notNull ? " NOT NULL" : ""}${def}`);
    }
    console.log("\n  schema.sql cannot fix these: it only emits CREATE TABLE IF NOT EXISTS,");
    console.log("  which is a no-op on a table that already exists. Run the idempotent");
    console.log("  migration that owns the change, e.g.:");
    console.log("    npm run db:migrate-prod");
    process.exit(1);
  }

  if (absentTables.length) process.exit(1);
  console.log("\nOK  every column in schema.prisma exists in the database.");
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
